// Public Suffix List lookups, following the algorithm at publicsuffix.org/list/.
export class PublicSuffixList {
    private readonly rules = new Set<string>();
    // "*.ck" is stored as "ck"
    private readonly wildcards = new Set<string>();
    // "!www.ck" is stored as "www.ck"
    private readonly exceptions = new Set<string>();

    constructor(rulesText: string) {
        for (const rule of rulesText.split("\n")) {
            if (rule.startsWith("!")) {
                this.exceptions.add(rule.substring(1));
            } else if (rule.startsWith("*.")) {
                this.wildcards.add(rule.substring(2));
            } else if (rule) {
                this.rules.add(rule);
            }
        }
    }

    // The public suffix plus one label, eg. "amazon.co.uk"; undefined if host is itself a suffix.
    public registrableDomain(host: string): string | undefined {
        const labels = host.toLowerCase().split(".");
        if (labels.some((label) => label.length === 0)) {
            return undefined;
        }
        const suffixLength = this.publicSuffixLength(labels);
        if (labels.length <= suffixLength) {
            return undefined;
        }
        return labels.slice(-(suffixLength + 1)).join(".");
    }

    private publicSuffixLength(labels: string[]): number {
        const tail = (from: number) => labels.slice(from).join(".");

        // an exception beats every other rule; its suffix drops the exception's first label
        for (let i = 0; i < labels.length; ++i) {
            if (this.exceptions.has(tail(i))) {
                return labels.length - i - 1;
            }
        }
        // otherwise the longest matching rule wins; "*" is the implicit default
        for (let i = 0; i < labels.length; ++i) {
            if (
                this.rules.has(tail(i)) ||
                (i + 1 < labels.length && this.wildcards.has(tail(i + 1)))
            ) {
                return labels.length - i;
            }
        }
        return 1;
    }
}
