import type { PublicSuffixList } from "./public_suffix_list";

// The domain feeds the hash, so the original quirks are kept: only sites under multi-label
// suffixes like "co.uk" differ from the original "last two labels".
export function extractDomain(URL: string, suffixes: PublicSuffixList): string | undefined {
    if (URL.length > 0) {
        // look for :// and remove up to it
        let startOfAddress = URL.indexOf("://");
        if (startOfAddress === -1) {
            startOfAddress = 0;
        } else {
            startOfAddress = startOfAddress + 3;
        }

        // find either the end of file or the first /
        let endOfAddress = URL.indexOf("/", startOfAddress);

        if (endOfAddress === -1) {
            endOfAddress = URL.length;
        }

        const registrable = suffixes.registrableDomain(URL.substring(startOfAddress, endOfAddress));
        if (registrable && registrable.split(".").length > 2) {
            return registrable;
        }

        // there must be at least one period
        const TLDpoint = URL.lastIndexOf(".", endOfAddress);
        if (TLDpoint === -1) {
            return;
        }

        // and the domain must exist (actually just check length)
        if (TLDpoint >= endOfAddress - 2) {
            return;
        }

        // good. now find the previous dot or start
        let domainStart = URL.lastIndexOf(".", TLDpoint - 1);
        if (domainStart === -1) {
            domainStart = startOfAddress;
        } else {
            ++domainStart;
        }

        return URL.substring(domainStart, endOfAddress);
    } else {
        return;
    }
}
