import React from "react";
import { extractDomain } from "./domain";
import { PublicSuffixList } from "./public_suffix_list";
import { PUBLIC_SUFFIXES } from "./public_suffixes";
import { FormSectionStyle, DescriptionStyle, HintStyle, InputStyle } from "./styles";

const SUFFIXES = new PublicSuffixList(PUBLIC_SUFFIXES);

declare class UIDomainInputProps {
    public onDomainPicked: (domain: string | undefined) => void;
}

export function UIDomainInput({ onDomainPicked }: UIDomainInputProps): JSX.Element {
    const [selectedDomain, setSelectedDomain] = React.useState<string | undefined>(undefined);

    const renderHint = (): string => {
        if (selectedDomain) {
            return selectedDomain;
        }
        return "URL not recognized";
    };

    const renderOk = (): string => {
        return selectedDomain ? " ✔️" : "";
    };

    const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        e.target.value = e.target.value.toLowerCase();
        const domain = extractDomain(e.target.value, SUFFIXES);

        setSelectedDomain(domain);

        onDomainPicked(domain);
    };

    return (
        <FormSectionStyle>
            <DescriptionStyle>
                <span>Enter the URL of your site{renderOk()}</span>
                <br />
                <HintStyle>{renderHint()}</HintStyle>
            </DescriptionStyle>
            <InputStyle
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="off"
                autoFocus
                spellCheck={false}
                type="url"
                onChange={onChange}
            />
            <br />
        </FormSectionStyle>
    );
}
